using System.Text.Json;
using System.Text.Json.Serialization;

namespace EwCapture.Core.Recognition;

/// <summary>One stash slot at a 1440-pixel-high client area. Item is null for an open slot.</summary>
public sealed record Slot(double X, double Y, double W, double H, string? Item, string? Icon);

/// <summary>One special tab (or sub-tab) layout from the game data, with its calibrated origin correction.</summary>
public sealed record Layout(string Label, int[] Offset, Slot[] Slots);

/// <summary>What GET /api/scanner/layouts returns (generated by tools/layouts).</summary>
public sealed record LayoutSet(string Version, string Patch, Dictionary<string, Layout> Layouts)
{
    static readonly JsonSerializerOptions Options = new() { PropertyNamingPolicy = JsonNamingPolicy.CamelCase };

    public static LayoutSet Parse(string json) =>
        JsonSerializer.Deserialize<LayoutSet>(json, Options) ?? throw new JsonException("empty layouts");
}

/// <summary>An item picture as straight RGBA, top row first.</summary>
public sealed record IconImage(int Width, int Height, byte[] Rgba);

/// <summary>Supplies item pictures by their GGG CDN path; null when not available (yet).</summary>
public interface IIconSource
{
    IconImage? Get(string path);
}
